#ifndef KERNEL_H
#define KERNEL_H

#include <ap_fixed.h>
#include <ap_int.h>
#include <stdint.h>

// ---------------------------------------------------------------------------
// Type definitions derived from params.yaml
// ---------------------------------------------------------------------------
// acm / A matrix:  bits=22, signed=1, fraction=0  => ap_fixed<23,23>
// max_iter:        bits=16, signed=0, fraction=0  => ap_uint<16>
// eigenvalues out: bits=22, signed=1, fraction=0  => ap_fixed<23,23>
// eigenvectors out:bits=22, signed=1, fraction=20 => ap_fixed<23,3>
// ite out:         bits=16, signed=0, fraction=0  => ap_uint<16>

typedef ap_fixed<23, 23> acm_t;      // real/imag component of input matrix
typedef ap_uint<16>      iter_t;     // max_iter / ite
typedef ap_fixed<23, 23> eval_t;     // eigenvalue real/imag component
typedef ap_fixed<23,  3> evec_t;     // eigenvector real/imag component

static const int N = 10;

// ---------------------------------------------------------------------------
// Top-level function declaration
// ---------------------------------------------------------------------------
void kernel_top(
    // Input: A[N][N] complex  -> real and imag parts split
    acm_t  A_re[N][N],
    acm_t  A_im[N][N],
    // Input: scalar
    iter_t max_iter,
    // Output: eigenvalues[N] complex
    eval_t eigenvalues_re[N],
    eval_t eigenvalues_im[N],
    // Output: eigenvectors[N][N] complex
    evec_t eigenvectors_re[N][N],
    evec_t eigenvectors_im[N][N],
    // Output: iteration count
    iter_t &ite,
    // C-sim cycle-count proxy
    uint32_t &clock_cycles
);

#endif // KERNEL_H
