#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include "kernel.h"

// ---------------------------------------------------------------------------
// Paths (call-index 0 only)
// ---------------------------------------------------------------------------
static const char IO_DIR[]  = "/home/mbenton/verilog_rapid_prototyping/conversion_018/eig_10_io/";
static const char SIM_DIR[] = "/home/mbenton/verilog_rapid_prototyping/conversion_018/build/sim/";

// ---------------------------------------------------------------------------
// Helper: open a file or abort
// ---------------------------------------------------------------------------
static FILE* xfopen(const char* path, const char* mode) {
    FILE* f = fopen(path, mode);
    if (!f) {
        fprintf(stderr, "ERROR: cannot open '%s'\n", path);
        exit(1);
    }
    return f;
}

// ---------------------------------------------------------------------------
// main
// ---------------------------------------------------------------------------
int main() {
    // ------------------------------------------------------------------
    // Allocate IO arrays
    // ------------------------------------------------------------------
    static acm_t  A_re[N][N];
    static acm_t  A_im[N][N];
    static iter_t max_iter_val;

    static eval_t eigenvalues_re[N];
    static eval_t eigenvalues_im[N];
    static evec_t eigenvectors_re[N][N];
    static evec_t eigenvectors_im[N][N];
    static iter_t ite_val;
    static uint32_t clock_cycles = 0;

    // ------------------------------------------------------------------
    // Read in_A.txt  (call index 0 = first N*N complex elements)
    // Each element is "real imag" on one line, row-major
    // The file contains 10 captures * 10*10 = 1000 entries; read only
    // the first 100.
    // ------------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sin_A.txt", IO_DIR);
        FILE* f = xfopen(path, "r");
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                double re, im;
                if (fscanf(f, "%lf %lf", &re, &im) != 2) {
                    fprintf(stderr, "ERROR: unexpected EOF reading in_A.txt at [%d][%d]\n", i, j);
                    fclose(f);
                    exit(1);
                }
                A_re[i][j] = (acm_t)re;
                A_im[i][j] = (acm_t)im;
            }
        }
        fclose(f);
    }

    // ------------------------------------------------------------------
    // Read in_max_iter.txt (call index 0 = first scalar)
    // ------------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sin_max_iter.txt", IO_DIR);
        FILE* f = xfopen(path, "r");
        long long v;
        if (fscanf(f, "%lld", &v) != 1) {
            fprintf(stderr, "ERROR: unexpected EOF reading in_max_iter.txt\n");
            fclose(f);
            exit(1);
        }
        max_iter_val = (iter_t)v;
        fclose(f);
    }

    // ------------------------------------------------------------------
    // Call kernel
    // ------------------------------------------------------------------
    kernel_top(
        A_re, A_im,
        max_iter_val,
        eigenvalues_re, eigenvalues_im,
        eigenvectors_re, eigenvectors_im,
        ite_val,
        clock_cycles
    );

    // ------------------------------------------------------------------
    // Write out_0.txt  (eigenvalues, complex, shape [10])
    // ------------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sout_0.txt", SIM_DIR);
        FILE* f = xfopen(path, "w");
        for (int i = 0; i < N; i++) {
            fprintf(f, "%.10f %.10f\n",
                    (double)eigenvalues_re[i],
                    (double)eigenvalues_im[i]);
        }
        fclose(f);
    }

    // ------------------------------------------------------------------
    // Write out_1.txt  (eigenvectors, complex, shape [10][10])
    // ------------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sout_1.txt", SIM_DIR);
        FILE* f = xfopen(path, "w");
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                fprintf(f, "%.10f %.10f\n",
                        (double)eigenvectors_re[i][j],
                        (double)eigenvectors_im[i][j]);
            }
        }
        fclose(f);
    }

    // ------------------------------------------------------------------
    // Write out_2.txt  (ite, scalar integer)
    // ------------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sout_2.txt", SIM_DIR);
        FILE* f = xfopen(path, "w");
        fprintf(f, "%u\n", (unsigned)ite_val);
        fclose(f);
    }

    // ------------------------------------------------------------------
    // Write clock_cycles.txt
    // ------------------------------------------------------------------
    {
        char path[512];
        snprintf(path, sizeof(path), "%sclock_cycles.txt", SIM_DIR);
        FILE* f = xfopen(path, "w");
        fprintf(f, "%u\n", clock_cycles);
        fclose(f);
    }

    printf("kernel_top finished: ite=%u  clock_cycles=%u\n",
           (unsigned)ite_val, clock_cycles);
    return 0;
}
